python3 -c "
import json
with open('BellevueWeather/BellevueWeather/BellevueWeather.flow') as f:
    data = json.load(f)

nodes = {n['id']: n for n in data['nodes']}
edges = data['edges']

print('=== Nodes ===')
for nid, n in nodes.items():
    print(f'  {nid} ({n[\"type\"]})')

print()
print('=== Edges ===')
for e in edges:
    print(f'  {e[\"sourceNodeId\"]}:{e[\"sourcePort\"]} -> {e[\"targetNodeId\"]}:{e[\"targetPort\"]}')

print()
print('=== Validation ===')
errors = []

# Check all edge node references exist
for e in edges:
    if e['sourceNodeId'] not in nodes:
        errors.append(f'Edge {e[\"id\"]}: source node \"{e[\"sourceNodeId\"]}\" not found')
    if e['targetNodeId'] not in nodes:
        errors.append(f'Edge {e[\"id\"]}: target node \"{e[\"targetNodeId\"]}\" not found')

# Check decision node has both true and false edges
decision_sources = {e['sourcePort'] for e in edges if e['sourceNodeId'] == 'checkTemperature'}
for port in ['true', 'false']:
    if port not in decision_sources:
        errors.append(f'checkTemperature missing outgoing edge on port \"{port}\"')

# Check both branches lead to formatSummary
for port in ['true', 'false']:
    targets = [e['targetNodeId'] for e in edges if e['sourceNodeId'] == 'checkTemperature' and e['sourcePort'] == port]
    if targets != ['formatSummary']:
        errors.append(f'checkTemperature:{port} does not go to formatSummary (goes to {targets})')

# Check formatSummary -> end
fs_targets = [e['targetNodeId'] for e in edges if e['sourceNodeId'] == 'formatSummary']
if fs_targets != ['end']:
    errors.append(f'formatSummary does not go to end (goes to {fs_targets})')

# Check decision expression references getWeather (not formatSummary)
check_node = nodes['checkTemperature']
expr = check_node['inputs']['expression']
if 'getWeather' not in expr:
    errors.append(f'checkTemperature expression does not reference getWeather: {expr}')
if 'formatSummary' in expr:
    errors.append(f'checkTemperature expression still references old formatSummary: {expr}')
print(f'  checkTemperature expression: {expr}')

# Check formatSummary script references checkTemperature for message
fs_node = nodes['formatSummary']
script = fs_node['inputs']['script']
if 'checkTemperature' not in script:
    errors.append('formatSummary script does not reference checkTemperature')
if 'nice day' not in script:
    errors.append('formatSummary script missing \"nice day\" message')
if 'bring a jacket' not in script:
    errors.append('formatSummary script missing \"bring a jacket\" message')
print(f'  formatSummary script: {script[:120]}...')

# Check single end node
end_nodes = [n for n in data['nodes'] if n['type'] == 'core.control.end']
if len(end_nodes) != 1:
    errors.append(f'Expected 1 end node, found {len(end_nodes)}: {[n[\"id\"] for n in end_nodes]}')

# Check layout keys match node ids
layout_ids = set(data['layout']['nodes'].keys())
node_ids = set(nodes.keys())
if layout_ids != node_ids:
    extra_layout = layout_ids - node_ids
    missing_layout = node_ids - layout_ids
    if extra_layout:
        errors.append(f'Layout has extra node keys not in nodes: {extra_layout}')
    if missing_layout:
        errors.append(f'Layout missing keys for nodes: {missing_layout}')

# Check variables reference valid nodes
for v in data['variables']['nodes']:
    if v['binding']['nodeId'] not in nodes:
        errors.append(f'Variable {v[\"id\"]} references non-existent node {v[\"binding\"][\"nodeId\"]}')

if errors:
    print()
    print('ERRORS:')
    for e in errors:
        print(f'  ❌ {e}')
else:
    print()
    print('✅ All validation checks passed!')
"

